      //   // \u65E0\u4EFB\u4F55\u53EF\u7528\\n      //   if (!(ipList.length > 0)) {\\n      //     return ipByDevice ? this.getUrl(ipByDevice) : null;\\n      //   }\\n\\n      //   if (ipByDevice && ipList.includes(ipByDevice)) {\\n      //     return this.getUrl(ipByDevice);\\n      //   }\\n\\n      //   return this.getUrl(ipList[0]);\\n      // }\\n    },\\n    watch: {\\n      msg: function (msg, prevMsg) {\\n        try {\\n          //debounce \u9632\u6296\\n          if (\\n            prevMsg &&\\n            prevMsg.interfaces &&\\n            JSON.stringify(prevMsg.interfaces) ===\\n              JSON.stringify(msg.interfaces)\\n          ) {\\n            console.log(\'\u{1F648}\u{1F648} Same msg: Skip....\')\\n            return;\\n          }\\n        } catch (e) {\\n          console.log(e);\\n        }\\n        this.scanning(msg);\\n      }\\n    },\\n    methods: {\\n      getUrl(ipAddress) {\\n        return `http://${window.location.hostname}/#/security?disablelayout=1`;\\n      },\\n      scanning(msg) {\\n        if (!(msg && msg.interfaces)) {\\n          return;\\n        }\\n        this.ipByDevice = this.getIpByDevice(msg.interfaces);\\n        this.scaningAddreses(msg.interfaces);\\n      },\\n      getIpByDevice: function (addresses) {\\n        const ipAddress =\\n          (this.deviceType === \\"PC\\"\\n            ? addresses[\\"usb\\"] || addresses[\\"wlan\\"]\\n            : addresses[\\"wlan\\"] || addresses[\\"usb\\"]) ||\\n          addresses[\\"eth\\"] ||\\n          addresses[\\"en\\"];\\n        if (!ipAddress) {\\n          return null;\\n        }\\n        return ipAddress;\\n      },\\n\\n      scaningAddreses: function (addresses) {\\n        if (!addresses || this.isScaning) {\\n          return;\\n        }\\n        console.log(\\"scanning addresses\\");\\n        const self = this;\\n        let results = [];\\n        var keys = Object.keys(addresses);\\n        const len = keys.length;\\n        self.isScaning = true;\\n\\n        let fn = (i) => {\\n          if (\\n            i >= len ||\\n            (!self.checkAllIps && self.enabledIpList.length > 0)\\n          ) {\\n            self.isScaning = false;\\n            self.enabledIpList = results;\\n            console.log(\\n              `%cScaning Finished \u2705\\\\n\u2728Enabled Addresses: ${self.enabledIpList.join(\\n                \\",\\"\\n              )}`,\\n              \\"color:#87ba32\\"\\n            );\\n\\n            fn = () => {};\\n            return;\\n          }\\n          let src = self.getUrl(addresses[keys[i]]);\\n          const xhr = new XMLHttpRequest();\\n          xhr.timeout = self.scanningTimeout;\\n\\n          const errorFn = () => {\\n            fn(++i);\\n          };\\n\\n          xhr.onload = function () {\\n            if (xhr.status >= 200 && xhr.status < 300) {\\n              results.push(addresses[keys[i]]);\\n              console.log(\\n                `%c\u2728(${i + 1}/${len})ping test Success: ${src}`,\\n                \\"color: #87ba32;\\"\\n              );\\n              fn(++i);\\n              return;\\n            }\\n            errorFn();\\n          };\\n\\n          xhr.onerror = function () {\\n            errorFn();\\n            console.log(\\n              `%c\u{1F6A5}(${i + 1}/${len}) ping test error: ${src}`,\\n              \\"color:red\\"\\n            );\\n          };\\n          // \u5B9A\u4E49\u8D85\u65F6\u56DE\u8C03\\n          xhr.ontimeout = function () {\\n            console.log(\\n              `%c\u{1F6A5}(${i + 1}/${len}) ping test timeout: ${src}`,\\n              \\"color:red;\\"\\n            );\\n            errorFn();\\n          };\\n\\n          console.log(\\n            `%c\u{1F6A5}(${i + 1}/${len}) start ping test: ${src}`,\\n            \\"color: #d8eeff;\\"\\n          );\\n          xhr.open(\\"GET\\", src, true);\\n          // \u53D1\u9001\u8BF7\u6C42\\n          xhr.send();\\n        };\\n        fn(0);\\n      },\\n\\n      // \u83B7\u53D6\u6240\u6709\u53EF\u7528IP\\n      getIpAddresses: function (interfaces) {\\n        const reg = /^(wlan|usb|eth|en)/;\\n        const addresses = {};\\n        for (let iface in interfaces) {\\n          for (let i = 0; i < interfaces[iface].length; i++) {\\n            let address = interfaces[iface][i];\\n            /* Ipv4 & \u6392\u9664\u5185\u90E8\u63A5\u53E3 & \u5339\u914D\u5F53\u524D\u4F18\u5148\u7EA7\u7684\u7F51\u53E3\u540D\u79F0 */\\n            var matches = iface.match(reg);\\n            if (\\n              matches &&\\n              matches[1] &&\\n              address.family === \\"IPv4\\" &&\\n              !address.internal\\n            ) {\\n              addresses[matches[1]] = address.address;\\n            }\\n          }\\n        }\\n        return addresses;\\n      }\\n    },\\n    mounted() {\\n      this.scanning(this.msg);\\n    }\\n  };\\n<\/script>\\n<style>\\n  body,\\n  html {\\n    overflow: hidden;\\n    margin: 0 0 0 0;\\n    padding: 0 0 0 0;\\n  }\\n\\n  #iframe_block {\\n    overflow: auto;\\n    margin: 0 0 0 0;\\n    padding: 0 0 0 0;\\n    box-sizing: border-box;\\n    top: 0;\\n    left: 0;\\n    width: 100%;\\n    height: 100%;\\n    min-height: 500px;\\n    z-index: 10000;\\n    background-color: #eee;\\n    display: flex;\\n    align-items: center;\\n    justify-content: center;\\n  }\\n\\n  #iframe_block iframe {\\n    width: 100%;\\n    height: 100%;\\n    border: 0;\\n    margin: 0 0 0 0;\\n    padding: 0 0 0 0;\\n    box-sizing: border-box;\\n  }\\n\\n  .skeleton_box {\\n    width: 50%;\\n    height: 50%;\\n    background: #e0e0e0;\\n    border-radius: 20px;\\n    position: relative;\\n    overflow: hidden;\\n  }\\n\\n  .skeleton_box::after {\\n    content: \\"\\";\\n    position: absolute;\\n    top: 0;\\n    left: -100%;\\n    width: 100%;\\n    height: 100%;\\n    background: linear-gradient(90deg,\\n        rgba(255, 255, 255, 0) 0%,\\n        rgba(255, 255, 255, 0.5) 50%,\\n        rgba(2